<script setup lang="ts">
import { useI18n } from './i18n'
const { t, tm } = useI18n()
import type {PhotoshopImportState} from '../main/photoshop-controller'
defineProps<{state:PhotoshopImportState}>();defineEmits<{confirm:[id:string];cancel:[id:string|undefined]}>()
</script>
<template><div v-if="state.status!=='idle'" class="photoshop-backdrop"><section class="photoshop-panel" role="dialog" :aria-label="t('Photoshop conversion report')"><h2>{{ t('Import {filename}', {filename:state.filename || ''}) }}</h2><p v-if="state.status==='reading'">{{ t('Reading the Photoshop file to check conversion requirements…') }}</p><p v-else-if="state.status==='error'" role="alert">{{tm(state.error || '')}} {{ t('No document was opened.') }}</p><template v-else><p>{{t('{width} × {height} px · {layers} layers · {groups} folders', {width:state.width || 0,height:state.height || 0,layers:state.layers || 0,groups:state.groups || 0})}}</p><p>{{ t('Review these conversions. The current documents are preserved until you continue.') }}</p><ol v-if="state.conversions?.length"><li v-for="(item,index) in state.conversions" :key="index"><strong>{{item.layerName}} <small>{{t(item.kind)}}</small></strong><p>{{tm(item.message)}}</p></li></ol><p v-else>{{ t('Ordinary pixels, folders, supported blend modes and raster masks can be imported directly.') }}</p></template><footer><button :disabled="state.status==='committing'" @click="$emit('cancel',state.id)">{{ t('Cancel import') }}</button><button :disabled="state.status!=='awaiting'" @click="$emit('confirm',state.id!)">{{t(state.status==='committing'?'Opening…':'Continue import')}}</button></footer></section></div></template>
